-- 126: 字段权限全量迁移 — DB 成为唯一配置来源
-- 结构: {nodes: {"0": {field: perm}, "1": {...}}} — 节点0=发起阶段
-- 自动生成，需人工审核后执行

BEGIN;

-- 前置校验：确保 125 已执行（logistics_fee 表单类型存在）
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM migrations_history WHERE filename LIKE '125_%') THEN
    RAISE EXCEPTION '迁移 126 依赖 125，请先执行 125_logistics_fee_form_type.sql';
  END IF;
END $$;

-- 1. 迁移所有表单旧 initiation 到 nodes["0"]
UPDATE oa_form_types
SET field_permissions = jsonb_set(
  COALESCE(field_permissions, '{}'::jsonb),
  '{nodes,0}',
  COALESCE(field_permissions->'initiation', '{}'::jsonb)
) - 'initiation'
WHERE field_permissions ? 'initiation';

